  // If kat-input
  const actualInput = searchInput.shadowRoot ? searchInput.shadowRoot.querySelector('input') : searchInput;

  actualInput.focus();
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(actualInput, 'B07HDVVZ1B');
