  actualInput.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));

  // Also look for search icon/button
  const searchBtn = searchInput.parentElement?.querySelector('button, [class*="search"]') || 
                    searchInput.shadowRoot?.querySelector('button, [class*="search"]');
  if (searchBtn) searchBtn.click();

  return {
    searched: true,
    inputVal: actualInput.value,
